            self._color_celda(cv, hex_val)
            self._padding_celda(ct, 50, 50, 70, 70)
            self._padding_celda(cv, 80, 80, 70, 70)
            pt = ct.paragraphs[0]
            pt.alignment = WD_ALIGN_PARAGRAPH.CENTER
            rt = pt.add_run(tit_k)
            rt.bold = True
            rt.font.size = Pt(8)
            rt.font.color.rgb = RGBColor(255, 255, 255)

            pv = cv.paragraphs[0]
